import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./FemalePage.css";
import Footer from "./Footer";

export default function FemalePage() {
  const [expandedService, setExpandedService] = useState(null);
  const [expandedTeamMember, setExpandedTeamMember] = useState(null);
  const [master, setMaster] = useState("");
  const [service, setService] = useState("");
  const [name, setName] = useState("");
  const [feedbackText, setFeedbackText] = useState("");
  const isLoggedIn = false; // Replace with real auth
  const navigate = useNavigate();

  const handleServiceClick = (service) => {
    setExpandedService(expandedService === service ? null : service);
  };

  const handleTeamClick = (member) => {
    setExpandedTeamMember(expandedTeamMember === member ? null : member);
  };

  const handleBookingClick = () => {
    if (isLoggedIn) {
      navigate("/booking");
    } else {
      navigate("/signin", { state: { from: "/booking" } });
    }
  };

  const handleFeedbackSubmit = (e) => {
    e.preventDefault();
    if (!master || !service || !name || !feedbackText) {
      alert("Please fill in all fields!");
      return;
    }
    const newFeedback = { master, service, name, feedback: feedbackText };
    const existingFeedbacks = JSON.parse(localStorage.getItem("feedbacks")) || [];
    existingFeedbacks.push(newFeedback);
    localStorage.setItem("feedbacks", JSON.stringify(existingFeedbacks));
    alert("Thank you for your feedback!");
    setMaster("");
    setService("");
    setName("");
    setFeedbackText("");
  };

  const teamMembers = [
    { name: "Scarlett Johansson", feedback: "An expert in styling long hair!" },
    { name: "Emma Watson", feedback: "Best at creating modern and sleek styles." },
    { name: "Zendaya", feedback: "Amazing with curls and volume!" },
    { name: "Natalie Portman", feedback: "An artist with hair coloring and balayage." },
    { name: "Margot Robbie", feedback: "Superb at trendy, high-fashion styles." },
    { name: "Jessica Chastain", feedback: "Great with updos and evening looks." },
  ];

  const servicePrices = {
    "Haircuts": "$50",
    "Hair Coloring": "$80",
    "Blowouts": "$40",
    "Hair Styling": "$60",
  };

  return (
    <main className="female-page">
      <section id="hero-section" className="female-hero-section">
        <div className="female-hero-text">
          <h1>Embrace Your Beauty</h1>
          <p>
            Let us help you look and feel your best. Whether you're preparing for a special occasion or just need a fresh cut, we are here for you.
          </p>
        </div>
      </section>

      <section id="services" className="female-services-section">
        <h2>Our Premium Services</h2>
        <div className="female-services-grid">
          {Object.keys(servicePrices).map((service) => (
            <div
              key={service}
              className={`female-service-card ${expandedService === service ? "expanded" : ""}`}
              onClick={() => handleServiceClick(service)}
            >
              <img
                src={`/${service.toLowerCase().replace(/ /g, "-")}.jpg`}
                alt={service}
                className="female-service-image"
              />
              <h3>{service}</h3>
              <p className="service-price">{servicePrices[service]}</p>
              {expandedService === service && (
                <div className="service-details">
                  <p>Details about {service}. Includes price, duration, and what to expect.</p>
                  <button type="button" className="book-button" onClick={handleBookingClick}>
                    Book Appointment
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      </section>

      <section id="feedback" className="feedback-section">
        <h2>Client Feedback</h2>
        <div className="feedback-grid">
          <div className="feedback-image-container">
            <img src="/female-feedback-image.png" alt="Feedback" className="feedback-image" />
            <button type="button" className="book-button" onClick={handleBookingClick}>
              Book Appointment
            </button>
          </div>
          <div className="feedback-form-container">
            <form className="feedback-form" onSubmit={handleFeedbackSubmit}>
              <div className="form-group">
                <label htmlFor="master">Choose Master:</label>
                <select id="master" value={master} onChange={(e) => setMaster(e.target.value)} required>
                  <option value="">Select Master</option>
                  {teamMembers.map((m) => (
                    <option key={m.name} value={m.name}>
                      {m.name}
                    </option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label htmlFor="service">Choose Service:</label>
                <select id="service" value={service} onChange={(e) => setService(e.target.value)} required>
                  <option value="">Select Service</option>
                  {Object.keys(servicePrices).map((s) => (
                    <option key={s} value={s}>
                      {s}
                    </option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label htmlFor="name">Your Name:</label>
                <input type="text" id="name" value={name} onChange={(e) => setName(e.target.value)} required />
              </div>
              <div className="form-group">
                <label htmlFor="feedback">Your Feedback:</label>
                <textarea id="feedback" value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} rows="4" required />
              </div>
              <button type="submit" className="feedback-submit-button">
                Submit Feedback
              </button>
            </form>
          </div>
        </div>
      </section>

      <section id="team" className="female-team-section">
        <h2>Meet Our Team</h2>
        <div className="female-team-grid">
          {teamMembers.map((member) => (
            <div
              key={member.name}
              className={`team-card ${expandedTeamMember === member.name ? "expanded" : ""}`}
              onClick={() => handleTeamClick(member.name)}
            >
              <img src={`/${member.name.split(" ")[0].toLowerCase()}.jpg`} alt={member.name} className="team-image" />
              <p className="team-name">{member.name}</p>
              <p className="team-role">Stylist</p>
              {expandedTeamMember === member.name && (
                <div className="team-details">
                  <p>{member.name} is an expert in haircuts, color, and styling. Highly rated by clients.</p>
                  <p><strong>Client Feedback:</strong> {member.feedback}</p>
                  <button type="button" className="book-button" onClick={handleBookingClick}>
                    Book Appointment
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      </section>

      <Footer />
    </main>
  );
}
